-- The TRI-DEEP code key (Code keys -> Drilling -> TRI-DEEP), from the ISCAR
-- e-catalog's TRI-DEEP families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.trideep', $ck${"title": "TRI-DEEP code key – gundrills, deep drills and inserts", "subtitle": "Indexable deep drilling for all methods: GD-DH gundrills, DSD / DDD tube drills (single and double tube) and TOGT / LOGT / ZSGT inserts with chip splitting edges and a wiper", "example": "GD-DH 14.00-15D-M25-07", "decoder": "tri-deep", "sections": [{"key": "t-family", "title": "Tool – family", "sample": "GD-DH", "rows": [{"code": "GD-DH", "meaning": "Gundrill carrying indexable inserts"}, {"code": "GD-DHL", "meaning": "Long gundrill carrying indexable inserts"}, {"code": "GDH", "meaning": "Gundrill head carrying TOGT inserts"}, {"code": "DSD", "meaning": "Single tube (BTA) drill"}, {"code": "DDD", "meaning": "Double tube (ejector) drill"}]}, {"key": "t-dia", "title": "Tool – diameter", "rows": [{"code": "##.##", "meaning": "Diameter in mm"}, {"code": "##.##-##.##", "meaning": "Diameter range of the tube drill"}]}, {"key": "t-depth", "title": "Tool – drilling depth", "rows": [{"code": "##D", "meaning": "Drilling depth ratio (e.g. 15D = 15xD)"}]}, {"key": "t-driver", "title": "Tool – driver", "rows": [{"code": "…", "meaning": "Driver / shank code (e.g. M25, FM40, I0.75; see the catalog)"}]}, {"key": "t-insert", "title": "Tool – insert size", "rows": [{"code": "##", "meaning": "Size of the inserts it carries"}]}, {"key": "t-length", "title": "Tool – length", "rows": [{"code": "###", "meaning": "Overall length in mm"}, {"code": "####", "meaning": "Overall length in mm"}]}, {"key": "t-suffix", "title": "Tool – suffix", "rows": [{"code": "N", "meaning": "N version (see the catalog) (inferred)"}]}, {"key": "t-connection", "title": "Tube drill – thread connection", "rows": [{"code": "EF", "meaning": "External 4-start thread connection"}, {"code": "IF", "meaning": "Internal single-start thread connection"}]}, {"key": "t-line", "title": "Tool – line", "rows": [{"code": "FT", "meaning": "TRI-DEEP triangular inserts"}, {"code": "FTA", "meaning": "TRI-DEEP triangular inserts, A version (inferred)"}, {"code": "MKT", "meaning": "Gundrill head (MKT connection) (inferred)"}]}, {"key": "i-family", "title": "Insert – family", "sample": "TOGT", "rows": [{"code": "TOGT", "meaning": "3 chip splitting cutting edges, positive rake chipbreaker and a wiper"}, {"code": "LOGT", "meaning": "2 chip splitting cutting edges, positive rake chipbreaker and a wiper"}, {"code": "ZSGT", "meaning": "Single chip splitting cutting edge and a wiper"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10"}]}, {"key": "i-hand", "title": "Insert – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "DT", "meaning": "General use"}, {"code": "GF", "meaning": "For soft / ductile materials (inferred)"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
